package com.vandorlabs.neoforge.navigation.observer;
import java.util.*;import java.util.concurrent.*;import com.vandorlabs.persistence.JournalWorker;import com.vandorlabs.neoforge.transfer.*;import com.vandorlabs.machines.CoreLayout;import com.vandorlabs.redstone.ChannelList;import net.minecraft.core.*;import net.minecraft.nbt.*;import net.minecraft.server.level.*;import net.minecraft.world.level.*;import net.minecraft.world.level.block.Blocks;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.event.server.ServerStartedEvent;import net.neoforged.neoforge.event.tick.ServerTickEvent;
/** Three actual 4096-cell requests: two durable records, bounded third wait, automatic resume and cold ownership. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeObserverDirectoryChecks {
 private static final BlockPos[] ROOTS={new BlockPos(31,64,31),new BlockPos(32,64,31),new BlockPos(31,64,32)};private static final int[][] CORNERS={{15,15},{0,15},{15,0}};private static final UUID[] KEYS=new UUID[3];private static final CountDownLatch RELEASE=new CountDownLatch(1),STARTED=new CountDownLatch(1);private static ServerLevel world;private static Actor actor;private static int ticks,stage,checks,pendingTicks,lastPermissions;private static boolean done,resumed;private static Future<List<NativeTransferJournalFiles.Saved>> files;
 private static final class Actor extends net.neoforged.neoforge.common.util.FakePlayer{int permissionCalls;Actor(ServerLevel w){super(w,new com.mojang.authlib.GameProfile(new UUID(0,211033),"ObserverDirectory"));}@Override public boolean mayUseItemAt(BlockPos p,Direction side,net.minecraft.world.item.ItemStack held){permissionCalls++;return super.mayUseItemAt(p,side,held);}}
 private static boolean enabled(){return Boolean.getBoolean("vandorlabs.observerDirectoryChecks");}private static String phase(){return System.getProperty("vandorlabs.observerDirectoryPhase","write");}private static void need(boolean ok,String why){checks++;if(!ok)throw new AssertionError("Source directory stage="+stage+" tick="+ticks+": "+why);}private static NativeObserverEntity root(int index){return (NativeObserverEntity)world.getBlockEntity(ROOTS[index]);}
 private static java.nio.file.Path expected(){return world.getServer().getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).resolve("observer-directory-expected.nbt");}
 private static java.nio.file.Path directory(){return world.getServer().getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).resolve("vandorlabs/cell-journals").resolve(HexFormat.of().formatHex(world.dimension().location().toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)));}
 @SubscribeEvent public static void started(ServerStartedEvent event){if(!enabled())return;try{world=event.getServer().overworld();for(int x=0;x<=3;x++)for(int z=0;z<=3;z++){world.setChunkForced(x,z,true);world.getChunk(x,z);}actor=new Actor(world);actor.setGameMode(GameType.SURVIVAL);actor.setPos(31.5,61,31.5);var warmup=NativeCellTransactions.class.getDeclaredMethod("state",ServerLevel.class);warmup.setAccessible(true);warmup.invoke(null,world);if(phase().equals("read")){var saved=NbtIo.readCompressed(expected(),NbtAccounter.create(65536));for(int i=0;i<3;i++)KEYS[i]=saved.getUUID("Key"+i);stage=10;return;}
 for(int i=0;i<3;i++){var at=ROOTS[i];world.setBlock(at,NativeObserverBindings.CORES.get("standalone_dish").defaultBlockState(),3);KEYS[i]=root(i).key();root(i).configure(ChannelList.of(42),256);var l=new CoreLayout(16,16,16,Direction.NORTH.get3DDataValue(),CORNERS[i][0],CORNERS[i][1]);for(int x=0;x<16;x++)for(int y=0;y<16;y++)for(int z=0;z<16;z++){var p=at.offset(l.x(x,z),y,l.z(x,z));if(!p.equals(at))world.setBlock(p,l.frame(x,y,z)?NativeObserverFormation.matter().defaultBlockState():Blocks.AIR.defaultBlockState(),3);}}
 JournalWorker.submit(()->{STARTED.countDown();if(!RELEASE.await(30,TimeUnit.SECONDS))throw new IllegalStateException("Directory disk gate timeout");return null;});for(int i=0;i<3;i++)need(NativeObserverTransactions.request(root(i),actor,true),"actual largest source request queued "+i);stage=0;
 }catch(Throwable failed){fail(failed);}}
 @SuppressWarnings("unchecked") private static Map<UUID,NativeCellTransactions.Operation<?>> operations()throws ReflectiveOperationException{var f=NativeCellTransactions.class.getDeclaredField("WORLDS");f.setAccessible(true);var state=((Map<ServerLevel,?>)f.get(null)).get(world);if(state==null)return Map.of();var entries=state.getClass().getDeclaredField("operations");entries.setAccessible(true);return (Map<UUID,NativeCellTransactions.Operation<?>>)entries.get(state);}
 private static long decoded()throws ReflectiveOperationException{var f=NativeCellTransactions.class.getDeclaredField("WORLDS");f.setAccessible(true);var state=((Map<?,?>)f.get(null)).get(world);var bytes=state.getClass().getDeclaredField("decodedBytes");bytes.setAccessible(true);return bytes.getLong(state);}
 private static void originals(){for(int i=0;i<3;i++)need(!root(i).formed()&&root(i).ownsRecovery()&&root(i).key().equals(KEYS[i]),"capacity wait leaves original native core unchanged "+i);}
 private static void verify(){for(int i=0;i<3;i++){var t=root(i);need(t.formed()&&t.available()&&t.key().equals(KEYS[i])&&t.design().width()==16,"exact largest source owner after completion/reload "+i);for(int x=0;x<16;x++)for(int y=0;y<16;y++)for(int z=0;z<16;z++){var p=t.cell(x,y,z);if(!p.equals(ROOTS[i]))need(world.getBlockEntity(p) instanceof NativeObserverPartEntity member&&member.root()==t,"all4095 members retain exact root "+i);}}need(NativeNavigationSources.matching(world,ROOTS[0],ChannelList.of(42)).size()==3,"all three sources supply distinct full coverage");}
 @SubscribeEvent public static void tick(ServerTickEvent.Post event){if(!enabled()||world==null||done)return;try{need(++ticks<1800,"bounded directory journey");var ops=operations();need(decoded()<=NativeTransferJournalFiles.MAX_NBT_BYTES,"cached recovery reservation never exceeds reader bound");if(stage==0){if(STARTED.getCount()!=0||ops.size()<2)return;need(ops.size()==2,"only two max records admitted while disk gate holds");originals();if(pendingTicks==0)lastPermissions=actor.permissionCalls;else need(actor.permissionCalls==lastPermissions,"capacity wait does not repeat full source authorization scans");need(!NativeTransferHolds.active(world),"non-durable preparing does not reserve or mutate sources");if(++pendingTicks<5)return;System.out.println("[vandorlabs][observer-directory] waiting PASS active="+ops.size()+" reservedDecoded="+decoded()+" thirdPending/noMutation");world.noSave=true;RELEASE.countDown();stage=1;return;}
 if(stage==1){if(ops.size()!=2||ops.values().stream().anyMatch(op->!op.reservationDurable()))return;originals();files=NativeTransferJournalFiles.load(directory());stage=2;return;}
 if(stage==2){if(!files.isDone())return;var records=files.get();long bytes=records.stream().mapToLong(saved->saved.record().sizeInBytes()).sum();need(records.size()==2&&bytes<=NativeTransferJournalFiles.MAX_NBT_BYTES&&decoded()==bytes+12,"actual asynchronous recovery loader reads both durable largest records");System.out.println("[vandorlabs][observer-directory] durable-read PASS files="+records.size()+" decoded="+bytes);world.noSave=false;stage=3;return;}
 if(stage==3){if(ops.values().stream().anyMatch(op->op.header.root().equals(ROOTS[2])))resumed=true;for(int i=0;i<3;i++)if(!root(i).formed()||!root(i).available())return;need(resumed,"third source automatically resumes after record retirement without another click");need(ops.isEmpty()&&decoded()==0,"retired records release exact cached byte reservation");verify();var saved=new CompoundTag();for(int i=0;i<3;i++)saved.putUUID("Key"+i,KEYS[i]);NbtIo.writeCompressed(saved,expected());world.getServer().saveEverything(false,true,true);finish("write");return;}
 if(stage==10&&ticks>=5){for(int i=0;i<3;i++)if(!root(i).available())return;verify();need(ops.isEmpty()&&decoded()==0,"cold directory retired cleanly");finish("read");}
 }catch(Throwable failed){fail(failed);}}
 private static void finish(String phase){done=true;System.out.println("[vandorlabs][observer-directory] "+phase+" PASS checks="+checks+" twoAdmitted/thirdPending/resumed/12288ownedCells/coldReload");world.getServer().halt(false);}private static void fail(Throwable failure){failure.printStackTrace();System.err.println("[vandorlabs][observer-directory] FAIL "+failure);RELEASE.countDown();done=true;if(world!=null){world.noSave=false;world.getServer().halt(false);}}
 private NativeObserverDirectoryChecks(){}
}
